B.T_=new A.dt("Apa itu kecepatan?","Kecepatan adalah jarak yang ditempuh dalam satu satuan waktu. Contoh: 60 km/jam artinya setiap 1 jam menempuh 60 km.",B.J_)
B.IP=s(["rumus","jkw","segitiga","jarak","waktu","kecepatan","cara","hitung"],t.s)
B.T1=new A.dt("Apa rumus jarak, kecepatan, dan waktu?","Jarak = kecepatan \xd7 waktu.\nKecepatan = jarak \xf7 waktu.\nWaktu = jarak \xf7 kecepatan.\nIngat segitiga JKW: J di atas, K dan W di bawah. Tutup yang dicari, lihat sisanya.",B.IP)
B.Jd=s(["menit","jam","ubah","konversi","satuan","bagi","60"],t.s)
B.SZ=new A.dt("Bagaimana mengubah menit ke jam?","Bagi dengan 60. Contoh: 30 menit = 30 \xf7 60 = 0,5 jam. 45 menit = 45 \xf7 60 = 0,75 jam.",B.Jd)
B.IE=s(["jam","menit","ubah","konversi","kali","60"],t.s)
B.T2=new A.dt("Bagaimana mengubah jam ke menit?","Kalikan dengan 60. Contoh: 1,5 jam = 1,5 \xd7 60 = 90 menit.",B.IE)
B.JH=s(["satuan","sama","samakan","menit","salah","kenapa"],t.s)
B.T6=new A.dt("Kenapa satuannya harus disamakan dulu?","Kalau kecepatan dalam km/jam tetapi waktu dalam menit, hasilnya pasti salah. Contoh: 6 km dalam 30 menit. 6 \xf7 30 = 0,2 itu salah. Ubah dulu 30 menit = 0,5 jam, lalu 6 \xf7 0,5 = 12 km/jam.",B.JH)
B.Jn=s(["km","meter","m","ubah","konversi","1000"],t.s)
B.T7=new A.dt("Bagaimana mengubah km ke m?","Kalikan dengan 1.000. Contoh: 3 km = 3 \xd7 1.000 = 3.000 m. Sebaliknya, m ke km dibagi 1.000.",B.Jn)
B.K8=s(["km/jam","m/detik","detik","ubah","konversi","3600"],t.s)
B.T9=new A.dt("Bagaimana mengubah km/jam ke m/detik?","Kalikan 1.000 (km ke m), lalu bagi 3.600 (jam ke detik). Contoh: 72 km/jam = 72 \xd7 1.000 \xf7 3.600 = 20 m/detik.",B.K8)
B.J3=s(["rata-rata","rata","total","andi"],t.s)
B.Ta=new A.dt("Apa itu kecepatan rata-rata?","Kecepatan rata-rata = total jarak \xf7 total waktu. Bukan rata-rata dari dua kecepatan! Contoh soal Andi: 10 km \xf7 1 jam = 10 km/jam.",B.J3)
B.KC=s(["pukul","jam","lama","berangkat","beda","waktu tempuh"],t.s)
B.T5=new A.dt("Apa bedanya jam berangkat dengan lama perjalanan?",'"Pukul 07.00" adalah jam (waktu pada jam dinding). "2 jam" atau "30 menit" adalah lama perjalanan. Yang dipakai di rumus adalah lama perjalanan.',B.KC)
B.Ko=s(["waktu tempuh","tempuh","lama"],t.s)
B.T0=new A.dt("Apa itu waktu tempuh?","Waktu tempuh adalah lama perjalanan dari tempat awal sampai tujuan.",B.Ko)
B.Kw=s(["rute","pilih","tepat waktu","batas","dina","bandingkan"],t.s)
B.T8=new A.dt("Bagaimana cara memilih rute yang tepat waktu?","Hitung waktu tiap rute (jarak \xf7 kecepatan), ubah ke menit, lalu bandingkan dengan batas waktunya. Pilih rute yang waktunya tidak melebihi batas.",B.Kw)
B.IM=s(["cek","masuk akal","periksa","logika","benar","salah","budi"],t.s)
B.SY=new A.dt("Bagaimana tahu jawabanku masuk akal?","Cek dengan logika. Kendaraan lebih cepat \u2192 waktunya lebih singkat. Kalikan kembali: kecepatan \xd7 waktu harus sama dengan jarak. Sepeda biasanya 10\u201320 km/jam. Kalau hasilmu 0,2 km/jam atau 180 km/jam, pasti ada yang salah.",B.IM)
B.Km=s(["15","30","45","menit","pecahan","seperempat","setengah"],t.s)
